                items = listOf(
                    CheatItem("lex_rest_graphql", "REST vs. GraphQL", "TL;DR: Feste URL-Endpunkte vs. flexible Client-Queries", "REST nutzt vordefinierte Endpunkte (Gefahr von Over-/Underfetching). GraphQL holt per POST exakt die deklarierten JSON-Felder in einem einzigen Request.", false, listOf("rest", "graphql", "api")),
                    CheatItem("lex_grpc_rest", "gRPC vs. REST", "TL;DR: Binäres HTTP/2 Protobuf vs. lesbares Text-JSON", "gRPC ist bis zu 10x schneller durch binäre Serialisierung und bidirektionales Streaming. Ideal für interne Microservice-Kommunikation.", false, listOf("grpc", "protobuf", "rpc")),
                    CheatItem("lex_docker_vm", "Docker Container vs. Virtuelle Maschine (VM)", "TL;DR: Shared Host-Kernel vs. vollständiges Gast-Betriebssystem", "Container teilen sich den Linux-Kernel des Hosts (leichtgewichtig, startet in ms). VMs emulieren komplette Hardware via Hypervisor (strikte Isolation, hoher RAM-Bedarf).", false, listOf("docker", "vm", "virtualization")),
                    CheatItem("lex_microservices", "Monolith vs. Microservices", "TL;DR: Eine gemeinsame Codebase vs. verteilte Services über Netzwerk", "Monolithen sind einfach zu testen und zu deployen. Microservices skalieren teamweise unabhängig, erhöhen aber Netzwerk-Latenz und Monitoring-Komplexität.", false, listOf("microservices", "monolith", "architecture")),
                    CheatItem("lex_serverless", "Serverless / FaaS (AWS Lambda)", "TL;DR: Nur Code ausführen – Abrechnung rein pro Millisekunde", "Entwickler verwalten keine Server oder Container. Funktionen werden ereignisbasiert gestartet und skalieren automatisch auf Null.", false, listOf("serverless", "cloud", "lambda")),
                    CheatItem("lex_event_driven", "Event-Driven Architecture (EDA)", "TL;DR: Entkoppelte Systeme kommunizieren über Ereignisse (Kafka/RabbitMQ)", "Producer senden Events ohne Empfänger zu kennen. Consumer reagieren asynchron. Erhöht Ausfallsicherheit und Durchsatz bei Lastspitzen.", false, listOf("events", "kafka", "queue")),
                    CheatItem("lex_cqrs", "CQRS (Command Query Responsibility Segregation)", "TL;DR: Getrennte Modelle für Schreiben (Command) und Lesen (Query)", "Lese- und Schreiboperationen werden auf unterschiedliche Datenbanken/Modelle aufgeteilt, um maximale Leseperformance zu erreichen.", false, listOf("cqrs", "architecture", "patterns")),
                    CheatItem("lex_reverse_proxy", "Reverse Proxy (Nginx, Traefik)", "TL;DR: Schutzschild & Router vor internen Backend-Servern", "Nimmt externe HTTP(S)-Anfragen entgegen, terminiert SSL, verteilt Last (Load Balancing) und routet an interne private Ports weiter.", false, listOf("proxy", "nginx", "networking")),
                    CheatItem("lex_api_gateway", "API Gateway", "TL;DR: Zentraler Einstiegspunkt für Client-Anfragen an Microservices", "Übernimmt Authentifizierung, Rate-Limiting, SSL-Terminierung, Caching und Request-Routing für Hunderte interne Microservices.", false, listOf("gateway", "api", "routing")),
                    CheatItem("lex_load_balancer", "Load Balancer (L4 vs L7)", "TL;DR: Lastverteiler auf Transport- (TCP) oder Applikationsebene (HTTP)", "L4 leitet IP-Pakete blitzschnell nach Port/IP weiter. L7 liest HTTP-Header, Cookies und Pfade aus, um intelligente Routing-Entscheidungen zu treffen.", false, listOf("loadbalancer", "cloud", "scaling")),
                    CheatItem("lex_cdn", "CDN (Content Delivery Network)", "TL;DR: Global verteilte Edge-Server für blitzschnelle Auslieferung", "Speichert statische Assets (Bilder, JS, CSS) weltweit in Servern nahe am Endnutzer, um Ladezeiten und Serverlast massiv zu senken.", false, listOf("cdn", "caching", "web")),
                    CheatItem("lex_webhooks", "Webhooks", "TL;DR: Umgekehrte API: Server ruft Client bei Ereignis per HTTP an", "Statt dass der Client minütlich nachfragt (Polling), sendet der Server sofort bei einem Event einen HTTP-POST-Request an eine Callback-URL.", false, listOf("webhook", "api", "events")),
                    CheatItem("lex_websocket_sse", "WebSockets vs. SSE (Server-Sent Events)", "TL;DR: Vollduplex-Kanal vs. unidirektionaler Server-zu-Client Stream", "WebSockets eignen sich für Chats und Multiplayer-Spiele. SSE nutzt einfaches HTTP für Live-Ticker, Benachrichtigungen oder LLM-Token-Streaming.", false, listOf("websocket", "sse", "streaming")),
                    CheatItem("lex_cors", "CORS (Cross-Origin Resource Sharing)", "TL;DR: Browser-Sicherheitsfilter gegen unberechtigte API-Aufrufe", "Verhindert, dass Skripte von domain-a.com heimlich AJAX-Requests an domain-b.com senden, es sei denn domain-b erlaubt es per Access-Control-Allow-Origin Header.", false, listOf("cors", "browser", "security")),
                    CheatItem("lex_dns", "DNS (Domain Name System)", "TL;DR: Das Telefonbuch des Internets (Domain -> IP)", "Löst menschenlesbare Namen (z.B. example.com) hierarchisch über Root-, TLD- und autoritative Nameserver in numerische IP-Adressen auf.", false, listOf("dns", "network", "web")),
                    CheatItem("lex_tls", "TLS / SSL Handshake", "TL;DR: Asymmetrischer Schlüsseltausch -> Symmetrische Verschlüsselung", "Server beweist Identität per Zertifikat. Diffie-Hellman-Einigung generiert Session-Key für die restliche AES-verschlüsselte Kommunikation.", false, listOf("tls", "ssl", "https")),
                    CheatItem("lex_http_versions", "HTTP/1.1 vs. HTTP/2 vs. HTTP/3", "TL;DR: Sequentiell -> Multiplexing -> UDP/QUIC", "HTTP/1.1 blockiert Verbindungen (Head-of-Line Blocking). HTTP/2 multiplexed Streams über ein TCP-Socket. HTTP/3 wechselt auf UDP (QUIC) gegen Paketverlust-Hänger.", false, listOf("http", "quic", "protocols")),
                    CheatItem("lex_cap", "CAP-Theorem", "TL;DR: In verteilten Systemen gehen nur 2 von 3: C, A oder P", "Consistency (alle sehen selbe Daten), Availability (immer Antwort) und Partition Tolerance (überlebt Netzausfall). Bei Netzwerktrennung muss man wählen.", false, listOf("cap", "database", "distributed")),
                    CheatItem("lex_edge_computing", "Edge Computing", "TL;DR: Datenverarbeitung direkt am Netzwerkrand beim Nutzer", "Berechnungen laufen auf CDN-Servern oder IoT-Gateways statt im fernen Rechenzentrum. Reduziert Latenz von 100ms auf 5ms.", false, listOf("edge", "cloud", "latency")),
                    CheatItem("lex_service_mesh", "Service Mesh (Istio / Linkerd)", "TL;DR: Dedizierte Infrastruktur-Schicht für Service-to-Service mTLS", "Sidecar-Proxies wickeln Verschlüsselung, Tracing, Retry-Logik und Circuit Breaking zwischen Microservices automatisch ab.", false, listOf("servicemesh", "istio", "k8s")),
                    CheatItem("lex_twelve_factor", "12-Factor App Prinzipien", "TL;DR: Best Practices für Cloud-Native Applikationen", "Enthält Regeln wie: Konfiguration nur über Umgebungsvariablen (Env), zustandslose Prozesse (Stateless), Port-Binding und Logs als Event-Streams.", false, listOf("12factor", "cloud", "devops")),
                    CheatItem("lex_idempotenz", "Idempotenz in APIs", "TL;DR: Mehrfache gleiche Aufrufe erzeugen denselben Zustand", "GET, PUT und DELETE sind idempotent. POST ist es nicht (erneutes Senden kann doppelten Kauf auslösen ohne Idempotency-Key).", false, listOf("api", "http", "idempotent")),
                    CheatItem("lex_rate_limiting", "Rate Limiting & Token Bucket", "TL;DR: Schutz vor API-Überlastung und DoS-Attacken", "Vergibt Anfragen-Token pro Zeitfenster (z.B. max 100 Requests/Min). Verhindert Missbrauch und drosselt aggressive Bots per HTTP 429.", false, listOf("ratelimit", "security", "api")),
                    CheatItem("lex_bff", "BFF (Backend for Frontend)", "TL;DR: Maßgeschneidertes Gateway pro Client-Typ (Web, Mobile)", "Ein separates Backend bereitet Daten speziell für mobile Apps (wenig Bandbreite) oder Desktop-Webclients optimiert auf.", false, listOf("bff", "architecture", "mobile")),
                    CheatItem("lex_forward_proxy", "Forward Proxy", "TL;DR: Proxy auf Client-Seite für Anonymität oder Firmenfilter", "Vermittelt Anfragen von internen Clients ins Internet. Versteckt Client-IP oder filtert unerwünschte Webseiten im Unternehmensnetz.", false, listOf("proxy", "forward", "network")),
                    CheatItem("lex_zero_trust", "Zero-Trust Architektur", "TL;DR: Niemals vertrauen, immer verifizieren ('Never Trust, Always Verify')", "Kein Benutzer oder Server genießt blindes Vertrauen, selbst innerhalb des Firmen-LANs. Jede einzelne Anfrage wird authentifiziert und autorisiert.", false, listOf("zerotrust", "security", "network"))
                )
            ),

