                    CheatItem("lex_systemd", "Systemd & Init-System", "TL;DR: PID 1 Prozess zur Verwaltung aller Systemdienste", "Initialisiert den Linux-Userspace, startet Dienste parallel mit Abhängigkeitsprüfung und sammelt Logs im einheitlichen Binärjournal.", false, listOf("systemd", "init", "linux")),
                    CheatItem("lex_cgroups_namespaces", "Cgroups & Namespaces", "TL;DR: Die Linux-Technologie, auf der Docker basiert", "Namespaces isolieren, was ein Prozess sieht (Dateisystem, PIDs, Netzwerk). Cgroups begrenzen, wie viel Ressourcen (CPU, RAM) er verbrauchen darf.", false, listOf("cgroups", "namespaces", "docker")),
                    CheatItem("lex_inodes", "Inodes (Index Nodes)", "TL;DR: Die Datenstruktur einer Datei ohne Dateiname", "Speichert Dateigröße, Besitzer, Zugriffsrechte und physische Festplattenblöcke. Der Dateiname steht nur als Verweis im Verzeichnis-Eintrag.", false, listOf("inode", "filesystem", "linux")),
                    CheatItem("lex_symlinks", "Hardlink vs. Symlink (Softlink)", "TL;DR: Direkter Inode-Pointer vs. Text-Pfad-Verknüpfung", "Hardlinks zeigen auf dieselben Datenblöcke (funktionieren nur auf selber Partition). Symlinks sind Dateiverweise wie Windows-Verknüpfungen.", false, listOf("symlink", "hardlink", "linux")),
                    CheatItem("lex_btrfs_ext4", "Btrfs vs. Ext4 Dateisystem", "TL;DR: Copy-on-Write mit Snapshots vs. felsenfester Standard", "Ext4 ist extrem stabil und bewährt. Btrfs bietet Prüfsummen gegen Bit-Rot, transparente Dateikomprimierung und sekundenschnelle Snapshots.", false, listOf("btrfs", "ext4", "filesystem")),
                    CheatItem("lex_zfs", "ZFS Dateisystem", "TL;DR: Enterprise Dateisystem + Volume-Manager in einem", "Bietet RAID-Z, Selbstheilung bei Datenkorruption, Snapshots und Skalierbarkeit für Petabytes an Enterprise-Speicher.", false, listOf("zfs", "storage", "enterprise")),
                    CheatItem("lex_swap_zram", "Swap-Speicher & ZRAM", "TL;DR: RAM-Überlauf auf SSD vs. komprimierter RAM", "Swap lagert inaktive Speicherseiten auf die SSD aus. ZRAM komprimiert diese Seiten direkt im schnellen Arbeitsspeicher per lz4-Algorithmus.", false, listOf("swap", "zram", "memory")),
                    CheatItem("lex_raid", "RAID Level (0, 1, 5, 10)", "TL;DR: Striping für Speed, Mirroring für Ausfallsicherheit", "RAID 0 = Doppelte Geschwindigkeit (kein Schutz). RAID 1 = Spiegelung. RAID 5 = Parität über min. 3 Platten. RAID 10 = Schnell & redundant.", false, listOf("raid", "storage", "hardware")),
                    CheatItem("lex_wayland_x11", "Wayland vs. X11 (Xorg)", "TL;DR: Moderne compositengestützte Sicherheit vs. 40 Jahre altes Protokoll", "X11 erlaubt jedem Fenster das Abgreifen aller Tastatureingaben (Keylogging-Gefahr). Wayland isoliert Fenster strikt; jeder Frame ist perfekt synchronisiert (kein Tearing).", false, listOf("wayland", "x11", "graphics")),
                    CheatItem("lex_pipewire", "PipeWire vs. PulseAudio", "TL;DR: Niedrige Latenz für Audio & sicheres Video-Sharing", "Vereint Audio und Wayland-Videoübertragung mit extrem niedrigen Latenzen für professionelle Musiker und Desktop-Streaming.", false, listOf("pipewire", "audio", "linux")),
                    CheatItem("lex_deadlock", "Deadlock (Verklemmung)", "TL;DR: Thread A wartet auf Ressource von B, und B auf A", "Vier Coffman-Bedingungen führen zum Stillstand: Mutual Exclusion, Hold & Wait, No Preemption und Circular Wait.", false, listOf("deadlock", "threads", "concurrency")),
                    CheatItem("lex_race_condition", "Race Condition & Mutex", "TL;DR: Unkontrollierter gleichzeitiger Schreibzugriff mehrerer Threads", "Entsteht wenn zwei Threads denselben Speicher ohne Synchronisation verändern. Lösung: Mutex (Mutual Exclusion Lock) oder atomare Operationen.", false, listOf("concurrency", "mutex", "threads")),
                    CheatItem("lex_memory_leak", "Memory Leak & OOM Killer", "TL;DR: Speicher allokiert, Referenz verloren, nie freigegeben", "Programm belegt immer mehr RAM, bis das Betriebssystem den Prozess per OOM-Killer (Out of Memory) gewaltsam beendet.", false, listOf("memory", "ram", "leak")),
                    CheatItem("lex_page_fault", "Page Fault & Virtueller Speicher", "TL;DR: CPU greift auf RAM-Seite zu, die noch auf SSD liegt", "Das Betriebssystem unterbricht den Prozess, lädt die angeforderte 4KB-Speicherseite von der Festplatte in den RAM und setzt das Programm fort.", false, listOf("mmu", "virtualmemory", "os")),
                    CheatItem("lex_dma", "DMA (Direct Memory Access)", "TL;DR: Hardware tauscht Daten mit RAM ohne CPU-Belastung", "Netzwerkkarten oder SSD-Controller schreiben Datenpakete direkt in den Arbeitsspeicher, ohne dass die CPU jedes Byte manuell kopieren muss.", false, listOf("dma", "hardware", "cpu")),
