                    CheatItem("lex_uefi_secure_boot", "UEFI & Secure Boot", "TL;DR: Moderner BIOS-Nachfolger mit digital signiertem Boot-Schutz", "UEFI bootet GPT-Festplatten über 2TB. Secure Boot verifiziert kryptografische Signaturen von Bootloader und Kernel gegen Root-Kits.", false, listOf("uefi", "secureboot", "firmware")),
                    CheatItem("lex_arm_x86", "ARM vs. x86-64 (RISC vs. CISC)", "TL;DR: Einfache Befehle & extreme Effizienz vs. komplexe Rechenpower", "ARM (Apple Silicon, Smartphones, Graviton) spart Transistoren und Strom durch feste Befehlslängen. x86 dominiert High-End-PCs und Legacy-Server.", false, listOf("arm", "x86", "architecture")),
                    CheatItem("lex_ecc_ram", "ECC RAM (Error-Correcting Code)", "TL;DR: RAM-Riegel korrigieren Bit-Flips durch kosmische Strahlung", "Erkennt und repariert spontane 1-Bit-Fehler im Speicher on-the-fly. Standard in Servern und NAS gegen unbemerkte Datenkorruption.", false, listOf("ecc", "ram", "hardware")),
                    CheatItem("lex_nvme_sata", "NVMe (PCIe) vs. SATA SSD", "TL;DR: 7.000 MB/s direkte PCIe-Lanes vs. 550 MB/s Flaschenhals", "SATA limitiert auf 6 Gbit/s mit AHCI (1 Warteschlange mit 32 Befehlen). NVMe nutzt PCIe direkt mit 64.000 Warteschlangen für parallele Flash-Zugriffe.", false, listOf("nvme", "ssd", "hardware")),
                    CheatItem("lex_spectre_meltdown", "Spectre & Meltdown", "TL;DR: Hardware-Sicherheitslücken in spekulativer CPU-Ausführung", "CPUs berechnen Code voraus. Sicherheitslücken im Cache erlaubten das Auslesen von Passwörtern über Prozess- und VM-Grenzen hinweg.", false, listOf("security", "cpu", "vulnerability")),
