                    CheatItem("lex_ransomware_backup", "Ransomware & 3-2-1 Backup-Regel", "TL;DR: Daten verschlüsselt -> Lösegeld gefordert", "Schutz gegen Erpressungstrojaner bietet die 3-2-1 Regel: 3 Kopien, 2 verschiedene Medien, 1 Kopie offline/außerhalb (Immutable/Air-Gapped).", false, listOf("ransomware", "backup", "321")),
                    CheatItem("lex_dns_spoofing", "DNS Spoofing & Cache Poisoning", "TL;DR: Gefälschte IP-Antwort leitet Opfer auf Phishing-Seite um", "Manipuliert den lokalen DNS-Cache des Routers oder Resolvers. Schutz bietet DNSSEC (kryptografische Signierung der Records).", false, listOf("dns", "spoofing", "dnssec")),
                    CheatItem("lex_arp_spoofing", "ARP Spoofing (Man-in-the-LAN)", "TL;DR: Angreifer gibt sich im WLAN als Router aus", "Sendet gefälschte ARP-Replies und leitet den gesamten Netzwerkverkehr des Raums über den eigenen Rechner um.", false, listOf("arp", "network", "mitm")),
                    CheatItem("lex_csp", "Content Security Policy (CSP)", "TL;DR: HTTP-Header legt erlaubte Skript-Quellen fest", "Weist den Browser an, Inline-Skripte und fremde Domains zu blockieren. Effektivster Browser-Schutz gegen XSS-Attacken.", false, listOf("csp", "header", "security")),
                    CheatItem("lex_buffer_overflow", "Buffer Overflow", "TL;DR: Programm schreibt über reservierten Speicherbereich hinaus", "Typisch für C/C++. Überschreibt Return-Adressen auf dem Call-Stack, um fremden Shellcode auszuführen. Abhilfe: Rust, ASLR, Stack Canaries.", false, listOf("overflow", "c", "exploit")),
                    CheatItem("lex_vpn_protocols", "WireGuard vs. OpenVPN", "TL;DR: 4.000 Zeilen moderner Kernel-Code vs. 100.000 Zeilen Legacy", "WireGuard ist extrem schnell, wechselt nahtlos zwischen WLAN/Mobilfunk und nutzt feste moderne Krypto (ChaCha20, Curve25519).", false, listOf("vpn", "wireguard", "openvpn")),
                    CheatItem("lex_supply_chain", "Supply Chain Attack", "TL;DR: Schadcode in Abhängigkeiten und Bibliotheken einschleusen", "Angreifer infizieren populäre Open-Source-Pakete (npm, PyPI) oder Build-Server, um tausende Downstream-Unternehmen auf einmal zu kompromittieren.", false, listOf("supplychain", "security", "npm")),
                    CheatItem("lex_social_engineering", "Phishing & Social Engineering", "TL;DR: Den Menschen als schwächstes Glied manipulieren", "Täuscht Dringlichkeit oder Autorität vor (CEO-Fraud, gefälschte Login-Mails), um 2FA-Codes oder Passwörter abzugreifen.", false, listOf("phishing", "security", "social")),
                    CheatItem("lex_selinux_apparmor", "SELinux vs. AppArmor", "TL;DR: Mandatory Access Control (MAC) im Linux-Kernel", "Selbst wenn ein Angreifer Root-Rechte in einem Dienst erlangt, verhindert die MAC-Policy das Ausbrechen aus dem definierten Profil.", false, listOf("selinux", "apparmor", "kernel")),
                    CheatItem("lex_honeypot", "Honeypot", "TL;DR: Absichtlich verwundbarer Köder-Server für Angreifer", "Dient als Frühwarnsystem und Analyse-Falle, um Angriffsmethoden und IP-Netze von Hackern in Echtzeit zu studieren.", false, listOf("honeypot", "security", "detection"))
                )
            ),

            // -----------------------------------------------------------------
            // Sektion 4: DevOps, Datenbanken, Git & Software-Engineering (26 Begriffe)
            // -----------------------------------------------------------------
            CheatSection(
                id = "lex_devops_db_git",
                title = "DevOps, Datenbanken, Git & Engineering",
                items = listOf(
                    CheatItem("lex_acid_base", "ACID vs. BASE", "TL;DR: Strikte Transaktionen vs. Eventual Consistency", "ACID (Postgres) garantiert Konsistenz zu jedem Zeitpunkt. BASE (NoSQL, Cassandra) setzt auf Verfügbarkeit und gleicht Daten erst verzögert ab.", false, listOf("acid", "base", "database")),
                    CheatItem("lex_sql_nosql", "SQL vs. NoSQL", "TL;DR: Tabellen mit Relationen vs. flexible Dokumente / Key-Value", "SQL für relationale Daten mit strengen Fremdschlüsseln. NoSQL für unstrukturierte Big Data, Caching (Redis) oder Dokumentenablage (Mongo).", false, listOf("sql", "nosql", "database")),
                    CheatItem("lex_db_sharding", "Sharding vs. Partitioning", "TL;DR: Horizontale Verteilung auf Server vs. Tabellenteilung lokal", "Partitionierung teilt große Tabellen lokal (z.B. nach Jahr). Sharding verteilt Kundendaten über separate Server-Cluster.", false, listOf("sharding", "database", "scale")),
                    CheatItem("lex_db_indexes", "Datenbank-Index (B-Tree vs. GIN/GiST)", "TL;DR: O(log N) Suchindex statt vollem Tabellenscan", "B-Tree beschleunigt Vergleiche (=, <, >). GIN/GiST indiziert Volltextsuche, Arrays, JSONB und Geo-Koordinaten blitzschnell.", false, listOf("index", "btree", "sql")),
                    CheatItem("lex_n_plus_one", "N+1 Query Problem", "TL;DR: Eine Abfrage holt Elternzeilen, N weitere Abfragen holen Kinder", "Verursacht hunderte unnötige Datenbankabfragen in ORMs. Lösung: Eager Loading / Joins (z.B. JOIN FETCH in SQL).", false, listOf("orm", "performance", "sql")),
                    CheatItem("lex_connection_pool", "Database Connection Pooling", "TL;DR: Offene Datenbankverbindungen wiederverwenden", "Der Verbindungsaufbau zu Postgres/MySQL ist teuer. Ein Pool (z.B. HikariCP) hält 10–50 Sockets warm und teilt sie unter Threads auf.", false, listOf("pool", "database", "hikaricp")),
                    CheatItem("lex_git_merge_rebase", "Git Merge vs. Git Rebase", "TL;DR: Echte Historie bewahren vs. saubere lineare Commit-Historie", "Merge erzeugt einen neuen Merge-Commit mit Verzweigung. Rebase pflanzt eigene Commits linear auf die Spitze des Ziel-Branches um.", false, listOf("git", "merge", "rebase")),
                    CheatItem("lex_git_reflog", "Git Reflog (Der Lebensretter)", "TL;DR: Tagebuch aller HEAD-Zeiger-Bewegungen", "Selbst nach einem versehentlichen 'git reset --hard' oder gelöschten Branches findet Reflog verlorene Commit-Hashes wieder.", false, listOf("git", "reflog", "rescue")),
                    CheatItem("lex_git_bisect", "Git Bisect", "TL;DR: Binäre Fehlersuche in der Commit-Historie", "Testet Commits automatisch halbierend durch, um den exakten Commit zu identifizieren, der einen Softwarefehler eingeführt hat.", false, listOf("git", "bisect", "debug")),
                    CheatItem("lex_ci_cd", "CI / CD Pipeline", "TL;DR: Automatisches Testen (CI) & automatisches Ausrollen (CD)", "Continuous Integration baut Code und führt Tests bei jedem Git-Push aus. Continuous Deployment spielt bestandene Builds automatisch auf Server aus.", false, listOf("cicd", "devops", "automation")),
                    CheatItem("lex_iac", "Infrastructure as Code (IaC)", "TL;DR: Server & Cloud per Code definieren (Terraform/Ansible)", "Keine manuellen Klicks im Cloud-Portal. Server, Firewalls und Datenbanken werden versioniert im Git deklarativ beschrieben.", false, listOf("iac", "terraform", "ansible")),
                    CheatItem("lex_k8s_pods", "Kubernetes Pods vs. Nodes", "TL;DR: Kleinste Container-Einheit vs. physischer/virtueller Host-Server", "Ein Pod kapselt einen oder mehrere Container mit gemeinsamer IP und Speicher. Ein Node ist der Server, auf dem viele Pods laufen.", false, listOf("k8s", "kubernetes", "pods")),
                    CheatItem("lex_blue_green", "Blue-Green Deployment vs. Canary", "TL;DR: Sofortiges Umschalten zweier Umgebungen vs. schrittweiser Rollout", "Blue-Green schaltet den Router sofort von Version Alt (Blau) auf Neu (Grün) um. Canary leitet erst 5 % der Nutzer auf die neue Version.", false, listOf("deployment", "devops", "canary")),
                    CheatItem("lex_tech_debt", "Technische Schulden (Technical Debt)", "TL;DR: Schneller Pfusch heute führt zu Zinsen (Entwicklungsbremse) morgen", "Bewusste Abkürzungen bei Architektur oder Tests beschleunigen das Release, erfordern aber später teure Refactorings.", false, listOf("refactoring", "code", "architecture")),
                    CheatItem("lex_dry_kiss", "DRY & KISS Prinzipien", "TL;DR: 'Don't Repeat Yourself' & 'Keep It Simple, Stupid'", "Vermeide redundante Codeduplikate und wähle stets die einfachste Architektur, die das Problem zuverlässig löst.", false, listOf("dry", "kiss", "principles")),
                    CheatItem("lex_solid", "SOLID Prinzipien", "TL;DR: Die 5 Säulen sauberer objektorientierter Software", "Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion.", false, listOf("solid", "oop", "clean")),
                    CheatItem("lex_tdd", "TDD (Test-Driven Development)", "TL;DR: Erst den Test schreiben (Rot), dann den Code (Grün), dann aufräumen", "Zwingt zu modularer, testbarer Architektur und verhindert ungetestete Randfälle.", false, listOf("tdd", "testing", "unit")),
                    CheatItem("lex_semver", "Semantic Versioning (SemVer)", "TL;DR: MAJOR.MINOR.PATCH (z.B. 2.4.1)", "MAJOR = Breaking Changes, MINOR = Neue abwärtskompatible Features, PATCH = Abwärtskompatible Bugfixes.", false, listOf("semver", "versioning", "git")),
                    CheatItem("lex_monorepo", "Monorepo vs. Polyrepo", "TL;DR: Alle Projekte in einem Git-Repo vs. ein Repo pro Service", "Monorepos (Google, Meta) erleichtern übergreifende Refactorings und gemeinsame Typen, fordern aber extrem schnelle CI-Tools.", false, listOf("monorepo", "git", "architecture")),
                    CheatItem("lex_observability", "Observability (Die 3 Säulen)", "TL;DR: Metrics, Logs und Distributed Tracing", "Metrics (CPU/Latenz) zeigen DASS ein Problem existiert. Logs zeigen WAS passiert ist. Traces zeigen WO im Microservice-Pfad der Flaschenhals liegt.", false, listOf("observability", "metrics", "tracing")),
                    CheatItem("lex_opentelemetry", "OpenTelemetry (OTel)", "TL;DR: Herstellerneutraler Standard für Telemetrie-Daten", "Einheitliche SDKs zum Erfassen von Metriken und Traces, exportierbar an Prometheus, Jaeger oder Datadog.", false, listOf("otel", "monitoring", "tracing")),
                    CheatItem("lex_cache_invalidation", "Cache-Invalidierung", "TL;DR: 'Es gibt nur zwei schwere Dinge: Cache-Invalidierung und Benennung'", "Wann löscht man veraltete Daten aus Redis? Strategien: TTL (Time to live), Cache-Aside, Write-Through oder Event-basiertes Löschen.", false, listOf("cache", "redis", "invalidation")),
                    CheatItem("lex_eventual_consistency", "Eventual Consistency", "TL;DR: Daten sind nicht sofort überall gleich, aber irgendwann garantiert", "Verteilte NoSQL-Systeme akzeptieren temporäre Abweichungen für maximale Schreibverfügbarkeit.", false, listOf("consistency", "distributed", "nosql")),
                    CheatItem("lex_concurrency_parallelism", "Concurrency vs. Parallelism", "TL;DR: Mehrere Aufgaben gleichzeitig handhaben vs. zeitgleich ausführen", "Concurrency ist Strukturierung (z.B. Event-Loop mit Async/Await). Parallelität erfordert mehrere echte CPU-Kerne.", false, listOf("async", "threads", "concurrency")),
                    CheatItem("lex_semantic_commit", "Conventional Commits", "TL;DR: feat:, fix:, docs:, chore:, refactor:", "Standardisiertes Commit-Format für automatisierte Changelog-Generierung und semantische Versionierung.", false, listOf("git", "commit", "standards")),
                    CheatItem("lex_circuit_breaker", "Circuit Breaker Pattern", "TL;DR: Schutz vor kaskadierenden Ausfällen in Microservices", "Wenn Service B fehlschlägt, öffnet der Circuit Breaker die Leitung und liefert sofort Fallbacks statt Requests anstauen zu lassen.", false, listOf("resilience", "microservices", "pattern"))
                )
            )
        )
    )
)
